static int checks;
static void Check(bool value,const char* text){if(!value)throw std::runtime_error(text);++checks;}
using Register=int32_t(*)(JaliumPlatformWindow*,JaliumAppleTabletCallback,void*);
static Register registerTablet;
static NSUInteger nextDevice=100;
static void Pump(){[NSRunLoop.currentRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.03]];}
struct Fixture {
 JaliumPlatformWindow* owner=nullptr;
 NSView* view;
 NSUInteger device=++nextDevice;
 bool accept=true;
 std::vector<JaliumAppleTabletEvent> events;
 std::vector<JaliumPlatformEvent> ordinary;
 std::function<void()> action;
 explicit Fixture(uint32_t style){JaliumWindowParams p{};p.title=reinterpret_cast<const uint16_t*>(u"Jalium tablet SDK");p.width=420;p.height=280;p.style=style;owner=jalium_window_create(&p);Check(owner,"create own tablet window");jalium_apple_window_show(owner,0);view=(__bridge NSView*)reinterpret_cast<void*>(jalium_window_get_native_handle(owner));Check(view.window.visible,"own tablet window visible");jalium_window_set_event_callback(owner,Mouse,this);Check(registerTablet(owner,Tablet,this)==0,"register optional tablet input");}
 ~Fixture(){if(owner)jalium_window_destroy(owner);}
 static int32_t Tablet(const JaliumAppleTabletEvent* e,void* c){auto* f=static_cast<Fixture*>(c);Check(e&&e->size==96&&e->pointer.pointer.pointerType==JALIUM_POINTER_PEN,"96-byte tablet record carries the existing pen event");f->events.push_back(*e);auto action=std::exchange(f->action,{});if(action)action();return f->accept;}
 static void Mouse(const JaliumPlatformEvent* e,void* c){if(e->type>=JALIUM_EVENT_MOUSE_MOVE&&e->type<=JALIUM_EVENT_MOUSE_LEAVE)static_cast<Fixture*>(c)->ordinary.push_back(*e);}
 JaliumTabletTestEvent* Event(NSEventType type,NSEventSubtype subtype,NSEventButtonMask buttons=0,float pressure=0){auto* e=[JaliumTabletTestEvent new];e.sampleType=type;e.sampleSubtype=subtype;e.sampleDevice=device;e.samplePoint=[view convertPoint:NSMakePoint(31.25,47.5) toView:nil];e.samplePressure=pressure;e.sampleTilt=NSMakePoint(.2,-.4);e.sampleRotation=-30;e.sampleButtons=buttons;e.sampleModifiers=NSEventModifierFlagCommand|NSEventModifierFlagShift;e.sampleTime=2+events.size()*.25;e.sampleClicks=2;return e;}
 void Proximity(NSPointingDeviceType tool=NSPointingDeviceTypePen,bool enter=true){auto* e=Event(NSEventTypeTabletProximity,NSEventSubtypeMouseEvent);e.sampleTool=tool;e.sampleEntering=enter;[view tabletProximity:e];}
 void Point(NSEventButtonMask buttons=0,float pressure=0){[view tabletPoint:Event(NSEventTypeTabletPoint,NSEventSubtypeMouseEvent,buttons,pressure)];}
 void Down(){[view mouseDown:Event(NSEventTypeLeftMouseDown,NSEventSubtypeTabletPoint,NSEventButtonMaskPenTip,.625)];}
 void Drag(){[view mouseDragged:Event(NSEventTypeLeftMouseDragged,NSEventSubtypeTabletPoint,NSEventButtonMaskPenTip,.8)];}
 void Up(){[view mouseUp:Event(NSEventTypeLeftMouseUp,NSEventSubtypeTabletPoint)];}
};
static void Run(uint32_t style){
 {Fixture f(style);f.Proximity();Check(f.events.empty(),"proximity does not invent a point or press");f.Point();auto hover=f.events.back();Check(hover.pointer.type==JALIUM_EVENT_POINTER_MOVE&&!(hover.pointer.pointer.flags&JALIUM_POINTER_FLAG_IN_CONTACT)&&hover.pointer.pointer.pressure==0,"native hover is in range without contact");f.Down();f.Drag();f.Point(NSEventButtonMaskPenTip,.4);f.Up();Check(f.events.size()==5,"mouse subtypes and native pressure packets share one input pipeline");auto id=hover.pointer.pointer.pointerId;for(const auto& e:f.events)Check(e.pointer.pointer.pointerId==id,"stable pointer identity throughout proximity");auto& down=f.events[1];Check(down.pointer.type==JALIUM_EVENT_POINTER_DOWN&&down.pointer.pointer.toolType==JALIUM_POINTER_TOOL_PEN,"physical tip starts pen contact");Check(down.pointer.pointer.pressure==.625f&&std::abs(down.pointer.pointer.tiltX-18)<1e-4&&std::abs(down.pointer.pointer.tiltY+36)<1e-4&&down.pointer.pointer.twist==330,"pressure scaled tilt and normalized rotation preserved");double scale=f.view.window.backingScaleFactor;Check(down.pointer.pointer.x==31.25*scale&&down.pointer.pointer.y==47.5*scale,"flipped physical client origin uses actual backing scale");Check(down.pointer.pointer.timestampMillis==2250&&down.pointer.pointer.modifiers==(JALIUM_MOD_META|JALIUM_MOD_SHIFT),"monotonic timestamp and physical modifiers");Check(down.mouseType==JALIUM_EVENT_MOUSE_DOWN&&down.mouseButton==0&&down.mouseClickCount==2&&(down.mouseButtonStates&1),"driver mouse down mapping and click count retained");Check(f.events[3].mouseType==0&&(f.events[3].pointer.pointer.flags&JALIUM_POINTER_FLAG_PRIMARY),"standalone pressure update stays primary without inventing a mouse event");Check(f.events.back().pointer.type==JALIUM_EVENT_POINTER_UP&&f.events.back().pointer.pointer.pressure==0&&!(f.events.back().mouseButtonStates&1),"tip release preserves range and releases compatibility button");Check(f.ordinary.empty(),"accepted tablet subtypes are not duplicated as ordinary mouse events");f.Proximity(NSPointingDeviceTypePen,false);Pump();Check(f.events.back().pointer.type==JALIUM_EVENT_POINTER_MOVE&&!(f.events.back().pointer.pointer.flags&JALIUM_POINTER_FLAG_IN_RANGE),"hover leaves proximity without inventing a click");}
 {Fixture f(style);f.Proximity(NSPointingDeviceTypeEraser);f.Down();const auto& p=f.events.back().pointer.pointer;Check(p.toolType==JALIUM_POINTER_TOOL_ERASER&&(p.flags&JALIUM_POINTER_FLAG_ERASER)&&(p.flags&JALIUM_POINTER_FLAG_INVERTED)&&(p.buttons&JALIUM_POINTER_BUTTON_ERASER),"eraser end preserves tool inversion and contact");f.Proximity(NSPointingDeviceTypeEraser,false);Pump();Check(f.events.back().pointer.type==JALIUM_EVENT_POINTER_CANCEL&&!(f.events.back().pointer.pointer.flags&JALIUM_POINTER_FLAG_IN_CONTACT),"proximity loss cancels an active contact");}
 {Fixture f(style);f.Proximity();auto* e=f.Event(NSEventTypeRightMouseDown,NSEventSubtypeTabletPoint,NSEventButtonMaskPenLowerSide|NSEventButtonMaskPenUpperSide);e.sampleButton=1;[f.view rightMouseDown:e];const auto& x=f.events.back();Check(x.pointer.type==JALIUM_EVENT_POINTER_MOVE&&!(x.pointer.pointer.flags&JALIUM_POINTER_FLAG_IN_CONTACT),"side buttons in hover do not fabricate contact");Check((x.pointer.pointer.buttons&(JALIUM_POINTER_BUTTON_SECONDARY|JALIUM_POINTER_BUTTON_TERTIARY|JALIUM_POINTER_BUTTON_BARREL))==(JALIUM_POINTER_BUTTON_SECONDARY|JALIUM_POINTER_BUTTON_TERTIARY|JALIUM_POINTER_BUTTON_BARREL),"two physical barrel switches remain distinct");Check(x.mouseType==JALIUM_EVENT_MOUSE_DOWN&&x.mouseButton==1&&(x.mouseButtonStates&2),"driver-assigned right button retained independently of tip");}
 {Fixture f(style);f.Proximity(NSPointingDeviceTypeCursor);f.Down();Check(f.events.empty()&&f.ordinary.size()==1,"tablet mouse puck retains its existing ordinary mouse path");}
 {Fixture f(style);f.accept=false;f.Proximity();f.Down();Check(f.events.size()==1&&f.ordinary.size()==1,"current declined tablet subtype retains ordinary mouse fallback");}
 for(int mutation=0;mutation<5;++mutation){Fixture f(style);f.accept=false;f.Proximity();f.action=[&]{if(mutation==0)jalium_window_hide(f.owner);else if(mutation==1){jalium_window_hide(f.owner);jalium_apple_window_show(f.owner,0);}else if(mutation==2){jalium_window_set_enabled(f.owner,0);jalium_window_set_enabled(f.owner,1);}else if(mutation==3)registerTablet(f.owner,nullptr,nullptr);else{auto* owner=f.owner;f.owner=nullptr;jalium_window_destroy(owner);}};f.Down();Check(f.ordinary.empty(),"retired tablet callback cannot fall through to ordinary mouse");}
 {Fixture f(style);f.Proximity();f.action=[&]{Check(jalium_apple_window_set_keyboard_focus(f.owner)==JALIUM_OK,"same content responder accepts keyboard focus");};f.Down();auto id=f.events.back().pointer.pointer.pointerId;f.Up();Check(f.events.size()==2&&f.events.back().pointer.type==JALIUM_EVENT_POINTER_UP&&f.events.back().pointer.pointer.pointerId==id,"ordinary keyboard focus preserves the physical pen down/up pair");}
 {Fixture f(style);f.Proximity();f.Down();jalium_window_hide(f.owner);jalium_apple_window_show(f.owner,0);Pump();auto n=f.events.size();f.Drag();Check(f.events.size()==n&&f.events.back().pointer.type==JALIUM_EVENT_POINTER_CANCEL,"hide/show retires contact and rejects its stale drag tail");f.Down();Check(f.events.back().pointer.type==JALIUM_EVENT_POINTER_DOWN,"fresh tip down recovers after cancellation");}
 {Fixture old(style);old.Proximity();old.Down();auto device=old.device;auto* owner=old.owner;old.owner=nullptr;jalium_window_destroy(owner);Fixture fresh(style);fresh.device=device;fresh.Drag();Check(fresh.events.empty()&&fresh.ordinary.empty(),"a held tip cannot begin a fresh press on a replacement native surface");fresh.Point();fresh.Point(NSEventButtonMaskPenTip,.5);Check(fresh.events.back().pointer.type==JALIUM_EVENT_POINTER_DOWN,"a witnessed tip release permits a subsequent native-only contact");}
 {Fixture f(style);f.Proximity();auto* e=f.Event(NSEventTypeLeftMouseDown,NSEventSubtypeTabletPoint,NSEventButtonMaskPenTip,.8);e.sampleTrigger=@selector(pressure);e->getter=[&]{f.Proximity();f.Down();};[f.view mouseDown:e];Check(f.events.size()==1&&f.events.back().pointer.pointer.pressure==.625f,"event getter reentry preserves the newer packet");}
 {Fixture f(style);f.Proximity();auto* e=f.Event(NSEventTypeLeftMouseDown,NSEventSubtypeTabletPoint,NSEventButtonMaskPenTip,.8);e.sampleTrigger=@selector(pressure);e->getter=[&]{auto* w=f.owner;f.owner=nullptr;jalium_window_destroy(w);};[f.view mouseDown:e];Check(f.events.empty(),"event getter destruction drops its packet before reading stale owner");}
 {Fixture f(style);f.Proximity();auto* e=f.Event(NSEventTypeLeftMouseDown,NSEventSubtypeTabletPoint,NSEventButtonMaskPenTip,NAN);[f.view mouseDown:e];Check(f.events.empty(),"nonfinite pen data is rejected");}
 {Fixture f(style);f.Proximity();auto first=f.device;f.Point(NSEventButtonMaskPenTip,.3);auto id=f.events.back().pointer.pointer.pointerId;f.device=++nextDevice;f.Proximity(NSPointingDeviceTypeEraser);f.Point(NSEventButtonMaskPenTip,.7);Check(f.events.back().pointer.pointer.pointerId!=id&&f.events.back().mouseType==0,"independent non-cursor transducer has a distinct pointer and no mouse mapping");f.device=first;f.Point(NSEventButtonMaskPenTip,.5);Check(f.events.back().pointer.pointer.pointerId==id,"interleaved devices preserve independent contact identity");}
 {Fixture f(style);f.Proximity();int result=0;std::thread thread([&]{result=registerTablet(f.owner,nullptr,nullptr);});thread.join();Check(result==JALIUM_ERROR_INVALID_STATE,"off-main registration is rejected");auto* e=f.Event(NSEventTypeTabletPoint,NSEventSubtypeMouseEvent);std::thread worker([&]{[f.view tabletPoint:e];});worker.join();Check(f.events.empty(),"off-main SDK packets are rejected before Cocoa queries");}
 {Fixture f(style|JALIUM_WINDOW_STYLE_INPUT_TRANSPARENT);f.Proximity();f.Down();Check(f.events.empty()&&f.ordinary.empty(),"input-transparent surface never claims tablet or compatibility mouse");}
 {Fixture f(style);f.Proximity();NSWindow* modal=[[NSWindow alloc]initWithContentRect:NSMakeRect(10,10,100,100) styleMask:NSWindowStyleMaskTitled backing:NSBackingStoreBuffered defer:NO];modal.releasedWhenClosed=NO;NSModalSession session=[NSApp beginModalSessionForWindow:modal];[NSApp runModalSession:session];Check(NSApp.modalWindow==modal,"real native modal scope installed");f.Down();Check(f.events.empty()&&f.ordinary.empty(),"foreign native modal excludes tablet input");[NSApp endModalSession:session];[modal close];}
}
static void RunInsideMainQueue(){
 __block bool finished=false,retired=false;
 dispatch_async(dispatch_get_main_queue(), ^{
  Fixture f(JALIUM_WINDOW_STYLE_TITLEBAR|JALIUM_WINDOW_STYLE_RESIZABLE);
  f.Proximity();f.Point();f.Proximity(NSPointingDeviceTypePen,false);Pump();
  retired=!f.events.empty()&&!(f.events.back().pointer.pointer.flags&JALIUM_POINTER_FLAG_IN_RANGE);
  finished=true;
 });
 Pump();Check(finished,"host can pump AppKit inside a main-queue callback");
 Check(retired,"deferred range exit is delivered while the main dispatch queue is occupied by its host");
}
int main(){@autoreleasepool{try{[NSApplication sharedApplication];registerTablet=reinterpret_cast<Register>(dlsym(RTLD_DEFAULT,"jalium_apple_window_set_tablet_callback"));Check(registerTablet,"optional tablet entry point exists");static_assert(sizeof(JaliumPlatformEvent)==72);static_assert(sizeof(JaliumAppleTabletEvent)==96);static_assert(offsetof(JaliumAppleTabletEvent,pointer)==8);for(uint32_t style:{uint32_t(JALIUM_WINDOW_STYLE_TITLEBAR|JALIUM_WINDOW_STYLE_RESIZABLE),uint32_t(JALIUM_WINDOW_STYLE_BORDERLESS|JALIUM_WINDOW_STYLE_RESIZABLE)})Run(style);RunInsideMainQueue();Pump();std::printf("PASS AppKit tablet protocol: %d checks; own SDK messages, no hardware tablet input\n",checks);return 0;}catch(const std::exception& e){std::fprintf(stderr,"FAIL AppKit tablet protocol: %s after %d checks\n",e.what(),checks);return 1;}}}
